python3 <<'PY'
import pathlib
path = pathlib.Path("src/offering/entities/offeringPackage.entity.ts")
text = path.read_text()

# Add imports if missing
old_import = "import { PaymentSchedule, aggregationMethod } from '../../dimensions/dto/create-dimension.dto.js';"
new_import = "import { PaymentSchedule, aggregationMethod, overageAllowedEnum } from '../../dimensions/dto/create-dimension.dto.js';\nimport { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';"
if old_import in text and "overageAllowedEnum" not in text:
    text = text.replace(old_import, new_import)

# Patch nonTiered section
old_snippet = """        Object.keys(dimensionTotals).forEach((dimensionId) => {
            let unitCost = Number(
                (parseFloat(nonTieredDimensionsMap[dimensionId].consumptionPrice) * exchangeRate).toFixed(
                    Offering.getDecimalsForNumber(parseFloat(nonTieredDimensionsMap[dimensionId].consumptionPrice)) ===
                        0
                        ? 2
                        : Offering.getDecimalsForNumber(
                              parseFloat(nonTieredDimensionsMap[dimensionId].consumptionPrice),
                          ),
                ),
            );
            if (nonTieredDimensionsMap[dimensionId]?.paymentSchedule === PaymentSchedule.upfront) {
                const billingMSStartDate = proratedStartDate ? proratedStartDate : startDate;
                const billingMSSeconds: number = Math.round(Math.abs(endDate.getTime() - billingMSStartDate.getTime()));
                const billingMSSecondsInBillingCycle = Offering.determineBillingSecondsInBillingCycle({
                    date: billingMSStartDate,
                    billingCycle: offeringInstance?.billingCycle,
                }) as number;
                unitCost = Math.round(100 * unitCost * (billingMSSeconds / billingMSSecondsInBillingCycle)) / 100;
            }
            const {
                usageIncrement,
                consumptionUnit: { unit, type },
            } = nonTieredDimensionsMap[dimensionId];
            // Handle currency conversion

            const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
                total: dimensionTotals[dimensionId],
                dimensionType: type,
                dimensionId,
                dimensionName: nonTieredDimensionsMap[dimensionId].dimensionName,
                offeringName: offeringInstance.offeringName,
                usageIncrement: parseInt(usageIncrement),
                dimensionUnit: unit,
                negative,
            });
            lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
        });"""

new_snippet = """        Object.keys(dimensionTotals).forEach((dimensionId) => {
            const dimension = nonTieredDimensionsMap[dimensionId];
            const totalRaw = dimensionTotals[dimensionId] as unknown as number;
            const total = typeof totalRaw === 'string' ? parseFloat(totalRaw as unknown as string) : (totalRaw as number);
            // Determine billable quantity based on allowance and overage
            let billable: number;
            const entitlement = dimension.usageEntitlement;
            const overageAllowed = dimension.overageAllowed;
            if (entitlement === undefined || entitlement === null) {
                billable = total;
            } else if (entitlement === 'inf') {
                billable = 0;
            } else if (overageAllowed !== overageAllowedEnum.true) {
                billable = 0;
            } else {
                const entNum = typeof entitlement === 'string' ? parseFloat(entitlement) : (entitlement as number);
                if (total > entNum) billable = total - entNum;
                else billable = 0;
            }
            if (billable <= 0) {
                // No chargeable quantity. Free dimensions with zero owed should not produce a line.
                // If price is zero and settings hide, also skip (already zero). If show and zero, we still skip zero quantity.
                return;
            }
            let unitCost = Number(
                (parseFloat(dimension.consumptionPrice) * exchangeRate).toFixed(
                    Offering.getDecimalsForNumber(parseFloat(dimension.consumptionPrice)) ===
                        0
                        ? 2
                        : Offering.getDecimalsForNumber(
                              parseFloat(dimension.consumptionPrice),
                          ),
                ),
            );
            if (dimension?.paymentSchedule === PaymentSchedule.upfront) {
                const billingMSStartDate = proratedStartDate ? proratedStartDate : startDate;
                const billingMSSeconds: number = Math.round(Math.abs(endDate.getTime() - billingMSStartDate.getTime()));
                const billingMSSecondsInBillingCycle = Offering.determineBillingSecondsInBillingCycle({
                    date: billingMSStartDate,
                    billingCycle: offeringInstance?.billingCycle,
                }) as number;
                unitCost = Math.round(100 * unitCost * (billingMSSeconds / billingMSSecondsInBillingCycle)) / 100;
            }
            // Hide free dimensions if settings dictate
            const isFree = unitCost === 0;
            if (isFree && offeringInstance?.settings?.freeDimensionOnInvoice === FreeDimensionOnInvoice.hide) {
                return;
            }
            const {
                usageIncrement,
                consumptionUnit: { unit, type },
            } = dimension;
            const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
                total: billable,
                dimensionType: type,
                dimensionId,
                dimensionName: dimension.dimensionName,
                offeringName: offeringInstance.offeringName,
                usageIncrement: parseInt(usageIncrement),
                dimensionUnit: unit,
                negative,
            });
            lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
        });"""

if old_snippet in text:
    text = text.replace(old_snippet, new_snippet)
    print("patched nonTiered")
else:
    print("old_snippet not found")
    # debug find
    import difflib
    # print around
    idx = text.find("Object.keys(dimensionTotals).forEach")
    print(text[idx-200:idx+2000])

path.write_text(text)
PY
}
